  public static func createWorldSnapshot(
    _ fbb: inout FlatBufferBuilder,
    schemaVersion: UInt32 = 2,
    siteOffset site: Offset = Offset(),
    stampNs: UInt64 = 0,
    frameOffset frame: Offset = Offset(),
    trackerOffset tracker: Offset = Offset(),
    unitsOffset units: Offset = Offset(),
    isKeyframe: Bool = true,
    entitiesVectorOffset entities: Offset = Offset(),
    removedIdsVectorOffset removedIds: Offset = Offset()
  ) -> Offset {
    let __start = twin_WorldSnapshot.startWorldSnapshot(&fbb)
    twin_WorldSnapshot.add(schemaVersion: schemaVersion, &fbb)
    twin_WorldSnapshot.add(site: site, &fbb)
    twin_WorldSnapshot.add(stampNs: stampNs, &fbb)
    twin_WorldSnapshot.add(frame: frame, &fbb)
    twin_WorldSnapshot.add(tracker: tracker, &fbb)
    twin_WorldSnapshot.add(units: units, &fbb)
    twin_WorldSnapshot.add(isKeyframe: isKeyframe, &fbb)
    twin_WorldSnapshot.addVectorOf(entities: entities, &fbb)
    twin_WorldSnapshot.addVectorOf(removedIds: removedIds, &fbb)
    return twin_WorldSnapshot.endWorldSnapshot(&fbb, start: __start)
